package com.thenerdcj.util;import com.thenerdcj.FoliaSkyblock;import org.bukkit.Bukkit;import org.bukkit.Location;import org.bukkit.entity.Entity;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import java.util.UUID;import java.util.concurrent.CompletableFuture;public final class ThreadSafety{private final FoliaSkyblock plugin;public ThreadSafety(FoliaSkyblock plugin){this.plugin=plugin;}public boolean isFolia(){return true;}private static long foliaSafeTicks(long ticks){return Math.max(1L,ticks);}public void runOnMainThread(Runnable task){if(task==null)return;plugin.getServer().getGlobalRegionScheduler().run(plugin,t->task.run());}public void runOnMainThreadLater(Runnable task,long delayTicks){if(task==null)return;plugin.getServer().getGlobalRegionScheduler().runDelayed(plugin,t->task.run(),foliaSafeTicks(delayTicks));}public void runRepeatingOnMainThread(Runnable task,long initialDelayTicks,long periodTicks){if(task==null)return;long i=foliaSafeTicks(initialDelayTicks),p=foliaSafeTicks(periodTicks);plugin.getServer().getGlobalRegionScheduler().runAtFixedRate(plugin,t->task.run(),i,p);}public void runAtLocation(Location loc,Runnable task){if(task==null||loc==null||loc.getWorld()==null)return;plugin.getServer().getRegionScheduler().run(plugin,loc,t->task.run());}public void runAtLocationLater(Location loc,Runnable task,long d){if(task==null||loc==null||loc.getWorld()==null)return;plugin.getServer().getRegionScheduler().runDelayed(plugin,loc,t->task.run(),foliaSafeTicks(d));}public void runForEntity(Entity e,Runnable task){if(task==null||e==null||!e.isValid())return;e.getScheduler().run(plugin,t->task.run(),null);}public void runForEntityLater(Entity e,Runnable task,long d){if(task==null||e==null||!e.isValid())return;e.getScheduler().runDelayed(plugin,t->task.run(),null,foliaSafeTicks(d));}public void runRepeatingForEntity(Entity e,Runnable task,long init,long per){if(task==null||e==null||!e.isValid())return;long i=foliaSafeTicks(init),p=foliaSafeTicks(per);e.getScheduler().runAtFixedRate(plugin,t->task.run(),null,i,p);}public Object runRepeatingForPlayer(Player pl,Runnable task,long init,long per){if(task==null||pl==null||!pl.isOnline())return null;long i=foliaSafeTicks(init),p=foliaSafeTicks(per);return pl.getScheduler().runAtFixedRate(plugin,t->task.run(),null,i,p);}public void runAsync(Runnable task){if(task==null)return;plugin.getServer().getAsyncScheduler().runNow(plugin,t->task.run());}public void giveItemSafely(UUID uuid,ItemStack item,String msg){runOnMainThread(()->{Player pl=Bukkit.getPlayer(uuid);if(pl!=null&&pl.isOnline()){pl.getInventory().addItem(item);if(msg!=null&&!msg.isEmpty())pl.sendMessage(msg);}else plugin.getDatabaseManager().storePendingItem(uuid,item);});}public void removeItemSafely(Player pl,ItemStack item){if(pl==null||item==null)return;runOnMainThread(()->{if(pl.isOnline())pl.getInventory().removeItem(item);});}public void sendMessageSafely(Player pl,String msg){if(pl==null||msg==null||msg.isEmpty())return;runOnMainThread(()->{if(pl.isOnline())pl.sendMessage(msg);});}public void sendMessageSafely(UUID uuid,String msg){if(uuid==null||msg==null||msg.isEmpty())return;runOnMainThread(()->{Player pl=Bukkit.getPlayer(uuid);if(pl!=null&&pl.isOnline())pl.sendMessage(msg);});}public <T> CompletableFuture<T> supplyOnMainThread(java.util.concurrent.Callable<T> task){CompletableFuture<T> f=new CompletableFuture<>();runOnMainThread(()->{try{f.complete(task.call());}catch(Exception e){f.completeExceptionally(e);}});return f;}}
